func (m *pageMap) resolveContentNodeForRef(context page.Page, isReflink, hadExtension bool, inRef, ref string) (contentNodeI, error) {
	s := m.lookupSite
	contentPathParser := m.lookupParser
	if contentPathParser == nil && s != nil {
		contentPathParser = s.Conf.PathParser()
	}

	if context != nil && !strings.HasPrefix(ref, "/") {
		var baseDir string
		if pi := context.PathInfo(); pi != nil {
			if pi.IsBranchBundle() || (hadExtension && strings.HasPrefix(ref, "../")) {
				baseDir = pi.Dir()
			} else {
				baseDir = pi.ContainerDir()
			}
		}

		rel := path.Join(baseDir, ref)
		relPath, _ := contentPathParser.ParseBaseAndBaseNameNoIdentifier(files.ComponentFolderContent, rel)
		n, err := m.resolveContentNodeFromPath(relPath, ref)
		if n != nil || err != nil {
			return n, err
		}

		if hadExtension && context.File() != nil {
			if n, err := m.resolveContentNodeFromReverseLookup(inRef, context.File().FileInfo()); n != nil || err != nil {
				return n, err
			}
		}
	}

	if strings.HasPrefix(ref, ".") {
		return nil, nil
	}

	relPath, nameNoIdentifier := contentPathParser.ParseBaseAndBaseNameNoIdentifier(files.ComponentFolderContent, ref)
	n, err := m.resolveContentNodeFromPath(relPath, ref)
	if n != nil || err != nil {
		return n, err
	}

	if hadExtension && s != nil && s.home != nil && s.home.File() != nil {
		if n, err := m.resolveContentNodeFromReverseLookup(inRef, s.home.File().FileInfo()); n != nil || err != nil {
			return n, err
		}
	}

	if !m.shouldDoSimpleNameLookup(isReflink, context, inRef, ref) {
		return nil, nil
	}

	n = m.lookupIndex.Get(nameNoIdentifier)
	if n == ambiguousContentNode {
		return nil, fmt.Errorf("page reference %q is ambiguous", inRef)
	}

	return n, nil
}

func (m *pageMap) shouldDoSimpleNameLookup(isReflink bool, context page.Page, inRef, ref string) bool {
	if m.lookupIndex == nil {
		return false
	}
	if m.lookupSite == nil {
		return false
	}
	if !(isReflink || context == nil) {
		return false
	}
	slashCount := strings.Count(inRef, "/")
	if slashCount > 1 {
		return false
	}
	return slashCount == 0 || (len(ref) > 0 && ref[0] == '/')
}

func (m *pageMap) resolveContentNodeFromReverseLookup(ref string, fi hugofs.FileMetaInfo) (contentNodeI, error) {
	s := m.lookupSite
	meta := fi.Meta()
	dir := meta.Filename
	if !fi.IsDir() {
		dir = filepath.Dir(meta.Filename)
	}

	realFilename := filepath.Join(dir, ref)
	pcs, err := s.BaseFs.Content.ReverseLookup(realFilename, true)
	if err != nil {
		return nil, err
	}

	parser := m.lookupParser
	if parser == nil {
		parser = s.Conf.PathParser()
	}

	for _, pc := range pcs {
		pi := parser.Parse(pc.Component, pc.Path)
		if n := m.lookupTree.Get(pi.Base()); n != nil {
			return n, nil
		}
	}
	return nil, nil
}

func (m *pageMap) resolveContentNodeFromPath(s string, ref string) (contentNodeI, error) {
	if m.lookupTree == nil {
		return nil, nil
	}
	if m.lookupSite == nil {
		return nil, nil
	}
	n := m.lookupTree.Get(s)
	if n != nil {
		return n, nil
	}
	return nil, nil
}

func (m *pageMap) listRegularPagesRecursive(p *pageState) page.Pages {
	include := m.listingLocal
	if include == nil {
		include = pagePredicates.ShouldListLocal
	}
	switch p.Kind() {
	case kinds.KindSection, kinds.KindHome:
		return m.listSectionPages(p, true, include.And(pagePredicates.KindPage))
	default:
		return m.listRegularPages(p)
	}
}

func (m *pageMap) listRegularPages(p *pageState) page.Pages {
	include := m.listingLocal
	if include == nil {
		include = pagePredicates.ShouldListLocal
	}
	switch p.Kind() {
	case kinds.KindPage:
	case kinds.KindSection, kinds.KindHome, kinds.KindTaxonomy:
		return m.listSectionPages(p, false, include.And(pagePredicates.KindPage))
	case kinds.KindTerm:
		return m.listTermPages(p, include.And(pagePredicates.KindPage))
	default:
		if m.listingSite != nil {
			return m.listingSite.RegularPages()
		}
	}
	return nil
}

func (m *pageMap) listPages(p *pageState) page.Pages {
	include := m.listingLocal
	if include == nil {
		include = pagePredicates.ShouldListLocal
	}
	switch p.Kind() {
	case kinds.KindPage:
	case kinds.KindSection, kinds.KindHome:
		return m.getPagesInSection(
			pageMapQueryPagesInSection{
				pageMapQueryPagesBelowPath: pageMapQueryPagesBelowPath{
					Path:    p.Path(),
					KeyPart: "page-section",
					Include: include.And(
						pagePredicates.KindPage.Or(pagePredicates.KindSection),
					),
				},
			},
		)
	case kinds.KindTerm:
		return m.listTermPages(p, include)
	case kinds.KindTaxonomy:
		return m.getPagesInSection(
			pageMapQueryPagesInSection{
				pageMapQueryPagesBelowPath: pageMapQueryPagesBelowPath{
					Path:    p.Path(),
					KeyPart: "term",
					Include: include.And(pagePredicates.KindTerm),
				},
				Recursive: true,
			},
		)
	default:
		if m.listingSite != nil {
			return m.listingSite.Pages()
		}
	}
	return nil
}

func (m *pageMap) listAllTranslations(p *pageState) page.Pages {
	_ = m.listingLocal
	key := p.Path() + "/" + "translations-all"
	pages, err := m.listingCache2.GetOrCreate(key, func(string) (page.Pages, error) {
		if p.m.pageConfig.TranslationKey != "" {
			pas, _ := m.listingSite.h.translationKeyPages.Get(p.m.pageConfig.TranslationKey)
			pasc := make(page.Pages, len(pas))
			copy(pasc, pas)
			page.SortByLanguage(pasc)
			return pasc, nil
		}
		var pas page.Pages
		m.listingTree.ForEeachInDimension(p.Path(), doctree.DimensionLanguage.Index(),
			func(n contentNodeI) bool {
				if n != nil {
					pas = append(pas, n.(page.Page))
				}
				return false
			},
		)
		pas = pagePredicates.ShouldLink.Filter(pas)
		page.SortByLanguage(pas)
